import numpy as np
from scipy.optimize import least_squares
obs=np.array([[334,229],[774,256],[752,628],[309,572]],float)
local=np.array([[-1,-1,0],[1,-1,0],[1,1,0],[-1,1,0]],float)
def Rz(a):
 c,s=np.cos(a),np.sin(a);return np.array([[c,-s,0],[s,c,0],[0,0,1]])
def Ry(a):
 c,s=np.cos(a),np.sin(a);return np.array([[c,0,s],[0,1,0],[-s,0,c]])
def Rx(a):
 c,s=np.cos(a),np.sin(a);return np.array([[1,0,0],[0,c,-s],[0,s,c]])
def fun(p):
 f,cx,cy,w,ar,yaw,pitch,roll=p
 h=w/ar
 pts=local*np.array([w/2,h/2,1])
 R=Rz(roll)@Ry(yaw)@Rx(pitch)
 cam=pts@R.T+np.array([cx,cy,1])
 proj=np.stack([f*cam[:,0]/cam[:,2]+640, f*cam[:,1]/cam[:,2]+360],1)
 return (proj-obs).ravel()
for ar in [1.2,1.25,1.3,1.35,1.4,1.414,1.45,1.5]:
 def f2(q):
  f,cx,cy,w,yaw,pitch,roll=q
  return fun([f,cx,cy,w,ar,yaw,pitch,roll])
 best=None
 for yaw0 in [-.2,-.1,0,.1,.2]:
  r=least_squares(f2,[500,0,0,.6,yaw0,0,0],max_nfev=30000,xtol=1e-12,ftol=1e-12,gtol=1e-12)
  if best is None or r.cost<best.cost: best=r
 r=best
 print(ar,round(r.cost,3),np.round(r.x,4),'max',abs(f2(r.x)).max())
PY"

