import numpy as np
from scipy.optimize import least_squares
obs=np.array([[334,229],[774,256],[752,628],[309,572]],float)
loc=np.array([[-1,-1],[1,-1],[1,1],[-1,1]],float)
def Rx(a):
 c,s=np.cos(a),np.sin(a);return np.array([[1,0,0],[0,c,-s],[0,s,c]])
def Ry(a):
 c,s=np.cos(a),np.sin(a);return np.array([[c,0,s],[0,1,0],[-s,0,c]])
def Rz(a):
 c,s=np.cos(a),np.sin(a);return np.array([[c,-s,0],[s,c,0],[0,0,1]])
def fun(p):
 f,w,h,yaw,pitch,roll,cx,cy,z=p
 pts=np.c_[loc*np.array([w/2,h/2]),np.zeros(4)]
 R=Rz(roll)@Ry(yaw)@Rx(pitch)
 cam=pts@R.T+np.array([cx,cy,z])
 uv=np.stack([f*cam[:,0]/cam[:,2]+640,f*cam[:,1]/cam[:,2]+360],1)
 return (uv-obs).ravel()
# fix yaw at several values, solve all including f, dims
for yaw in np.linspace(-1.4,1.4,15):
 def f2(q):
  f,w,h,pitch,roll,cx,cy,z=q
  return fun([f,w,h,yaw,pitch,roll,cx,cy,z])
 best=None
 for x0 in [[1000,.44,.36,.1,.08,0,0,1],[1000,.44,.36,-.1,.08,0,0,1]]:
  r=least_squares(f2,x0,bounds=([100,.05,.05,-1.5,-.5,-1,-1,.2],[10000,1,1,1.5,.5,1,1,5]),max_nfev=50000,xtol=1e-13,ftol=1e-13,gtol=1e-13)
  if best is None or r.cost<best.cost:best=r
 print(round(yaw,2),round(best.cost,4),np.round(best.x,4),'max',round(abs(f2(best.x)).max(),2))
PY"
